#!/usr/bin/env bash
# run.sh — MFL regression tests via `machin test` (framework/test.src is
# composed ahead of the sources; each test/*.src file brings its own main()).
#
# The suite sources compose like build.sh does, minus main.src (the test
# file supplies main). src/catalog_gen.src and src/version_gen.src are
# generated by build.sh — run it first if missing.
#
# MACHIN_365_HOME is pointed at a throwaway dir: sync_pass_once reads and
# writes sync manifests under the suite home, and tests must never touch
# the real one.
set -euo pipefail
cd "$(dirname "$0")/.."
if [ ! -f src/catalog_gen.src ] || [ ! -f src/version_gen.src ]; then ./build.sh >/dev/null; fi
export MACHIN_365_HOME="$(mktemp -d /tmp/m365-test-home.XXXXXX)"
SRCS=$(ls src/*.src | grep -v '/main\.src$')
machin test $SRCS test/*.src
